Below is a focused Pulumi TypeScript implementation of a `ComponentResource` wrapping the requested S3 bucket, PostgreSQL RDS instance, and Kubernetes service-account IAM role. It also implements production cross-region bucket replication and uses stack-encrypted configuration for the database password.

The EKS cluster and HTTPS resources from the broader canonical scenario should be composed separately; the component accepts the cluster’s OIDC provider details and existing private networking as inputs.

## Project structure

```text
.
├── Pulumi.yaml
├── Pulumi.dev.yaml
├── Pulumi.prod.yaml
├── package.json
├── tsconfig.json
├── index.ts
└── components/
    └── serviceInfrastructure.ts
```

## `components/serviceInfrastructure.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export type Environment = "dev" | "prod";

export interface ServiceInfrastructureArgs {
    environment: Environment;

    /**
     * Existing private subnets used by RDS.
     * Supply subnets in at least two availability zones.
     */
    privateSubnetIds: pulumi.Input<pulumi.Input<string>[]>;

    /**
     * Security groups controlling connectivity to PostgreSQL.
     * These should only allow port 5432 from the application/node security group.
     */
    databaseSecurityGroupIds: pulumi.Input<pulumi.Input<string>[]>;

    databaseName: pulumi.Input<string>;
    databaseUsername: pulumi.Input<string>;
    databasePassword: pulumi.Input<string>;

    /**
     * EKS OIDC provider details used by IRSA.
     */
    oidcProviderArn: pulumi.Input<string>;
    oidcProviderUrl: pulumi.Input<string>;

    kubernetesNamespace: pulumi.Input<string>;
    kubernetesServiceAccount: pulumi.Input<string>;

    tags?: pulumi.Input<Record<string, pulumi.Input<string>>>;
}

export class ServiceInfrastructure extends pulumi.ComponentResource {
    public readonly assetsBucket: aws.s3.Bucket;
    public readonly database: aws.rds.Instance;
    public readonly serviceAccountRole: aws.iam.Role;

    /**
     * Secret Pulumi Output. Pulumi preserves secrecy when this is exported.
     */
    public readonly databaseConnectionString: pulumi.Output<string>;

    constructor(
        name: string,
        args: ServiceInfrastructureArgs,
        opts?: pulumi.ComponentResourceOptions,
    ) {
        super("example:infrastructure:ServiceInfrastructure", name, {}, opts);

        const childOptions: pulumi.ResourceOptions = {
            parent: this,
        };

        const tags = pulumi
            .output(args.tags ?? {})
            .apply(customTags => ({
                ...customTags,
                Environment: args.environment,
                ManagedBy: "Pulumi",
                Component: name,
            }));

        //
        // S3 application assets bucket
        //

        this.assetsBucket = new aws.s3.Bucket(`${name}-assets`, {
            forceDestroy: args.environment === "dev",
            tags,
        }, childOptions);

        const bucketVersioning = new aws.s3.BucketVersioningV2(
            `${name}-assets-versioning`,
            {
                bucket: this.assetsBucket.id,
                versioningConfiguration: {
                    status: "Enabled",
                },
            },
            childOptions,
        );

        new aws.s3.BucketServerSideEncryptionConfigurationV2(
            `${name}-assets-encryption`,
            {
                bucket: this.assetsBucket.id,
                rules: [{
                    applyServerSideEncryptionByDefault: {
                        sseAlgorithm: "AES256",
                    },
                    bucketKeyEnabled: true,
                }],
            },
            childOptions,
        );

        new aws.s3.BucketPublicAccessBlock(
            `${name}-assets-public-access-block`,
            {
                bucket: this.assetsBucket.id,
                blockPublicAcls: true,
                blockPublicPolicy: true,
                ignorePublicAcls: true,
                restrictPublicBuckets: true,
            },
            childOptions,
        );

        // Deny all non-TLS access.
        new aws.s3.BucketPolicy(`${name}-assets-policy`, {
            bucket: this.assetsBucket.id,
            policy: pulumi.all([
                this.assetsBucket.arn,
            ]).apply(([bucketArn]) => JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Sid: "DenyInsecureTransport",
                    Effect: "Deny",
                    Principal: "*",
                    Action: "s3:*",
                    Resource: [
                        bucketArn,
                        `${bucketArn}/*`,
                    ],
                    Condition: {
                        Bool: {
                            "aws:SecureTransport": "false",
                        },
                    },
                }],
            })),
        }, childOptions);

        if (args.environment === "prod") {
            this.createCrossRegionReplication(
                name,
                bucketVersioning,
                tags,
            );
        }

        //
        // RDS PostgreSQL
        //

        const subnetGroup = new aws.rds.SubnetGroup(
            `${name}-db-subnets`,
            {
                subnetIds: args.privateSubnetIds,
                tags,
            },
            childOptions,
        );

        this.database = new aws.rds.Instance(`${name}-postgres`, {
            engine: "postgres",

            instanceClass: args.environment === "prod"
                ? "db.t3.medium"
                : "db.t3.micro",

            allocatedStorage: args.environment === "prod" ? 50 : 20,
            maxAllocatedStorage: args.environment === "prod" ? 200 : 100,

            dbName: args.databaseName,
            username: args.databaseUsername,
            password: pulumi.secret(args.databasePassword),
            port: 5432,

            dbSubnetGroupName: subnetGroup.name,
            vpcSecurityGroupIds: args.databaseSecurityGroupIds,

            publiclyAccessible: false,
            multiAz: args.environment === "prod",
            storageEncrypted: args.environment === "prod",

            deletionProtection: true,
            backupRetentionPeriod: args.environment === "prod" ? 30 : 7,
            backupWindow: "03:00-04:00",
            maintenanceWindow: "sun:04:30-sun:05:30",

            autoMinorVersionUpgrade: true,
            applyImmediately: args.environment === "dev",

            iamDatabaseAuthenticationEnabled: true,

            // Deletion protection must be explicitly disabled before destruction.
            skipFinalSnapshot: false,
            finalSnapshotIdentifier: `${name}-${args.environment}-final-snapshot`,

            copyTagsToSnapshot: true,
            tags,
        }, childOptions);

        //
        // IAM role for Kubernetes service account (IRSA)
        //

        const assumeRolePolicy = pulumi.all([
            args.oidcProviderArn,
            args.oidcProviderUrl,
            args.kubernetesNamespace,
            args.kubernetesServiceAccount,
        ]).apply(([
            providerArn,
            providerUrl,
            namespace,
            serviceAccount,
        ]) => {
            const issuer = providerUrl
                .replace(/^https?:\/\//, "")
                .replace(/\/$/, "");

            return JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Principal: {
                        Federated: providerArn,
                    },
                    Action: "sts:AssumeRoleWithWebIdentity",
                    Condition: {
                        StringEquals: {
                            [`${issuer}:aud`]: "sts.amazonaws.com",
                            [`${issuer}:sub`]:
                                `system:serviceaccount:${namespace}:${serviceAccount}`,
                        },
                    },
                }],
            });
        });

        this.serviceAccountRole = new aws.iam.Role(
            `${name}-service-account`,
            {
                assumeRolePolicy,
                description:
                    `IRSA role for ${name} in ${args.environment}`,
                tags,
            },
            childOptions,
        );

        const applicationPolicy = pulumi.all([
            this.assetsBucket.arn,
            this.database.resourceId,
            args.databaseUsername,
        ]).apply(([bucketArn, databaseResourceId, databaseUsername]) =>
            JSON.stringify({
                Version: "2012-10-17",
                Statement: [
                    {
                        Sid: "ListApplicationAssets",
                        Effect: "Allow",
                        Action: [
                            "s3:GetBucketLocation",
                            "s3:ListBucket",
                        ],
                        Resource: bucketArn,
                    },
                    {
                        Sid: "ManageApplicationAssets",
                        Effect: "Allow",
                        Action: [
                            "s3:GetObject",
                            "s3:GetObjectVersion",
                            "s3:PutObject",
                            "s3:DeleteObject",
                        ],
                        Resource: `${bucketArn}/*`,
                    },
                    {
                        Sid: "ConnectToApplicationDatabase",
                        Effect: "Allow",
                        Action: [
                            "rds-db:connect",
                        ],
                        Resource:
                            `arn:${aws.config.partition}:rds-db:` +
                            `${aws.config.region}:` +
                            `${aws.config.accountId}:dbuser:` +
                            `${databaseResourceId}/${databaseUsername}`,
                    },
                ],
            }),
        );

        new aws.iam.RolePolicy(`${name}-service-policy`, {
            role: this.serviceAccountRole.id,
            policy: applicationPolicy,
        }, childOptions);

        this.databaseConnectionString = pulumi.secret(
            pulumi.all([
                args.databaseUsername,
                args.databasePassword,
                this.database.address,
                this.database.port,
                args.databaseName,
            ]).apply(([
                username,
                password,
                host,
                port,
                databaseName,
            ]) => {
                const encodedUser = encodeURIComponent(username);
                const encodedPassword = encodeURIComponent(password);
                const encodedDatabase = encodeURIComponent(databaseName);

                return `postgresql://${encodedUser}:${encodedPassword}` +
                    `@${host}:${port}/${encodedDatabase}?sslmode=require`;
            }),
        );

        this.registerOutputs({
            assetsBucketName: this.assetsBucket.bucket,
            assetsBucketArn: this.assetsBucket.arn,
            databaseAddress: this.database.address,
            databasePort: this.database.port,
            databaseConnectionString: this.databaseConnectionString,
            serviceAccountRoleArn: this.serviceAccountRole.arn,
        });
    }

    private createCrossRegionReplication(
        name: string,
        sourceVersioning: aws.s3.BucketVersioningV2,
        tags: pulumi.Output<Record<string, pulumi.Input<string>>>,
    ): void {
        const replicationProvider = new aws.Provider(
            `${name}-replication-provider`,
            {
                region: "us-west-2",
            },
            { parent: this },
        );

        const replicaBucket = new aws.s3.Bucket(
            `${name}-assets-replica`,
            {
                forceDestroy: false,
                tags,
            },
            {
                parent: this,
                provider: replicationProvider,
            },
        );

        const replicaVersioning = new aws.s3.BucketVersioningV2(
            `${name}-assets-replica-versioning`,
            {
                bucket: replicaBucket.id,
                versioningConfiguration: {
                    status: "Enabled",
                },
            },
            {
                parent: this,
                provider: replicationProvider,
            },
        );

        new aws.s3.BucketServerSideEncryptionConfigurationV2(
            `${name}-assets-replica-encryption`,
            {
                bucket: replicaBucket.id,
                rules: [{
                    applyServerSideEncryptionByDefault: {
                        sseAlgorithm: "AES256",
                    },
                    bucketKeyEnabled: true,
                }],
            },
            {
                parent: this,
                provider: replicationProvider,
            },
        );

        new aws.s3.BucketPublicAccessBlock(
            `${name}-assets-replica-public-access-block`,
            {
                bucket: replicaBucket.id,
                blockPublicAcls: true,
                blockPublicPolicy: true,
                ignorePublicAcls: true,
                restrictPublicBuckets: true,
            },
            {
                parent: this,
                provider: replicationProvider,
            },
        );

        const replicationRole = new aws.iam.Role(
            `${name}-replication-role`,
            {
                assumeRolePolicy: aws.iam.assumeRolePolicyForPrincipal({
                    Service: "s3.amazonaws.com",
                }),
                tags,
            },
            { parent: this },
        );

        const replicationPolicy = new aws.iam.RolePolicy(
            `${name}-replication-policy`,
            {
                role: replicationRole.id,
                policy: pulumi.all([
                    this.assetsBucket.arn,
                    replicaBucket.arn,
                ]).apply(([sourceArn, destinationArn]) => JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [
                        {
                            Sid: "ReadSourceReplicationMetadata",
                            Effect: "Allow",
                            Action: [
                                "s3:GetReplicationConfiguration",
                                "s3:ListBucket",
                            ],
                            Resource: sourceArn,
                        },
                        {
                            Sid: "ReadSourceObjectVersions",
                            Effect: "Allow",
                            Action: [
                                "s3:GetObjectVersion",
                                "s3:GetObjectVersionAcl",
                                "s3:GetObjectVersionForReplication",
                                "s3:GetObjectVersionTagging",
                            ],
                            Resource: `${sourceArn}/*`,
                        },
                        {
                            Sid: "ReplicateToDestination",
                            Effect: "Allow",
                            Action: [
                                "s3:ReplicateDelete",
                                "s3:ReplicateObject",
                                "s3:ReplicateTags",
                            ],
                            Resource: `${destinationArn}/*`,
                        },
                    ],
                })),
            },
            { parent: this },
        );

        new aws.s3.BucketReplicationConfig(
            `${name}-assets-replication`,
            {
                bucket: this.assetsBucket.id,
                role: replicationRole.arn,
                rules: [{
                    id: "replicate-to-us-west-2",
                    status: "Enabled",
                    priority: 1,
                    filter: {
                        prefix: "",
                    },
                    deleteMarkerReplication: {
                        status: "Enabled",
                    },
                    destination: {
                        bucket: replicaBucket.arn,
                        storageClass: "STANDARD",
                    },
                }],
            },
            {
                parent: this,
                dependsOn: [
                    sourceVersioning,
                    replicaVersioning,
                    replicationPolicy,
                ],
            },
        );
    }
}
```

## `index.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import { ServiceInfrastructure } from "./components/serviceInfrastructure";

const config = new pulumi.Config();

const environment = config.require("environment");
if (environment !== "dev" && environment !== "prod") {
    throw new Error("environment must be either 'dev' or 'prod'");
}

const infrastructure = new ServiceInfrastructure("webapp", {
    environment,

    privateSubnetIds: config.requireObject<string[]>("privateSubnetIds"),
    databaseSecurityGroupIds:
        config.requireObject<string[]>("databaseSecurityGroupIds"),

    databaseName: config.get("databaseName") ?? "application",
    databaseUsername: config.get("databaseUsername") ?? "application",
    databasePassword: config.requireSecret("databasePassword"),

    oidcProviderArn: config.require("oidcProviderArn"),
    oidcProviderUrl: config.require("oidcProviderUrl"),

    kubernetesNamespace:
        config.get("kubernetesNamespace") ?? "application",
    kubernetesServiceAccount:
        config.get("kubernetesServiceAccount") ?? "webapp",

    tags: {
        Application: "webapp",
        Environment: environment,
    },
});

export const assetsBucketName = infrastructure.assetsBucket.bucket;
export const databaseAddress = infrastructure.database.address;
export const databaseConnectionString =
    infrastructure.databaseConnectionString;
export const serviceAccountRoleArn =
    infrastructure.serviceAccountRole.arn;
```

