runtime:
  name: nodejs
  options:
    typescript: true
description: Application bucket, PostgreSQL database, and IRSA role
```

## `Pulumi.dev.yaml`

```yaml
config:
  aws:region: us-east-1

  service-infrastructure:environment: dev
  service-infrastructure:databaseName: application
  service-infrastructure:databaseUsername: application

  service-infrastructure:privateSubnetIds:
    - subnet-dev-private-a
    - subnet-dev-private-b

  service-infrastructure:databaseSecurityGroupIds:
    - sg-dev-postgres

  service-infrastructure:oidcProviderArn: arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/DEVEXAMPLE
  service-infrastructure:oidcProviderUrl: https://oidc.eks.us-east-1.amazonaws.com/id/DEVEXAMPLE

  service-infrastructure:kubernetesNamespace: application
  service-infrastructure:kubernetesServiceAccount: webapp

  # Set with:
  # pulumi config set --stack dev --secret databasePassword '<value>'
  #
  # Pulumi writes an encrypted secure value here, never plaintext.
```

## `Pulumi.prod.yaml`

```yaml
config:
  aws:region: us-east-1

  service-infrastructure:environment: prod
  service-infrastructure:databaseName: application
  service-infrastructure:databaseUsername: application

  service-infrastructure:privateSubnetIds:
    - subnet-prod-private-a
    - subnet-prod-private-b
    - subnet-prod-private-c

  service-infrastructure:databaseSecurityGroupIds:
    - sg-prod-postgres

  service-infrastructure:oidcProviderArn: arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/PRODEXAMPLE
  service-infrastructure:oidcProviderUrl: https://oidc.eks.us-east-1.amazonaws.com/id/PRODEXAMPLE

  service-infrastructure:kubernetesNamespace: application
  service-infrastructure:kubernetesServiceAccount: webapp

  # Set with:
  # pulumi config set --stack prod --secret databasePassword '<value>'
```

Do not place example plaintext passwords in either stack file. Populate them using Pulumi secret configuration:

```bash
pulumi stack init dev
pulumi config set --stack dev --secret databasePassword '...'

pulumi stack init prod
pulumi config set --stack prod --secret databasePassword '...'
```

